<?php
namespace Tests\Feature;
use App\Models\Tenant; use App\Models\User; use App\Notifications\PayrollApprovedNotification; use App\Services\NotificationDispatcher; use Illuminate\Support\Facades\Notification; use Illuminate\Support\Str; use Tests\TestCase;
class NotificationDispatcherTest extends TestCase { public function test_notification_dedupe_key_sends_only_once():void{if(config('database.default')!=='mysql')$this->markTestSkipped('Requires MySQL.');$tenant=Tenant::create(['name'=>'Notify '.Str::random(4)]);try{tenancy()->initialize($tenant);Notification::fake();$u=User::create(['name'=>'E','email'=>Str::uuid().'@example.test','password'=>'secret123','role'=>'employee','active'=>true]);$d=app(NotificationDispatcher::class);$n=new PayrollApprovedNotification(1,9,2026,'500.000');$this->assertTrue($d->once($u,'payroll-approved:1',$n));$this->assertFalse($d->once($u,'payroll-approved:1',$n));Notification::assertSentToTimes($u,PayrollApprovedNotification::class,1);}finally{if(tenancy()->initialized)tenancy()->end();$tenant->delete();}} }
